R=Path(__file__).resolve().parents[3];D=Path(__file__).resolve().parent;E=html.escape
O=R/'downloads';O.mkdir(exist_ok=True)
font='/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf';bold='/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'
pdfmetrics.registerFont(TTFont('D2',font));pdfmetrics.registerFont(TTFont('D2B',bold))
INK=HexColor('#203d4a');TEAL=HexColor('#176c66');LINE=HexColor('#cbd8d1')
def base(c,title,subtitle,pg,total):
 c.setFillColor(TEAL);c.rect(0,750,612,42,fill=1,stroke=0);c.setFillColor(HexColor('#ffffff'));c.setFont('D2B',11);c.drawString(42,766,'NEXALYPLANNER / FREE WORKSHEET')
 c.setFillColor(INK);c.setFont('D2B',21);c.drawString(42,708,title);c.setFont('D2',9);c.drawString(42,686,subtitle);c.setFont('D2',8);c.drawString(42,28,'nexalyplanner.com | US Letter | Static writing sheet, not a fillable PDF');c.drawRightString(570,28,f'{pg} / {total}')
 c.setFont('D2',10);c.drawString(42,654,'Business / project: ____________________   Fixed date: ______________')
def section(c,y,title,prompt,lines=5):
 c.setFillColor(INK);c.setFont('D2B',12);c.drawString(42,y,title);c.setFont('D2',9)
 for n,line in enumerate(textwrap.wrap(prompt,99)):c.drawString(42,y-20-n*14,line)
 c.setStrokeColor(LINE)
 for n in range(lines):yy=y-49-n*24;c.line(42,yy,570,yy)
def plan_pdf():
 c=canvas.Canvas(str(O/'business-plan-template.pdf'),pagesize=letter);c.setTitle('Business Plan Template - Original Three-Page Worksheet');c.setAuthor('NexalyPlanner')
 groups=[[(1,'Customer and evidence','Who has the problem? What interviews, observations or orders support this?'),(2,'Offer and revenue model','What do you sell, to whom, at what unit/fee and with which scope limits?'),(3,'Market and alternatives','What alternatives exist? Record dated comparisons and untested assumptions.')],[(4,'Operations and capacity','Who delivers? List stock, hours, equipment, dependencies and acceptance criteria.'),(5,'Marketing and sales','Name the channel, test budget, sales steps, responsible owner and evidence.'),(6,'Costs, cash and funding','Separate sales, consumed costs, purchases, receipts and payments by date.')],[(7,'Risks and downside','Change one important assumption. What capacity or cash constraint breaks first?'),(8,'Actions and review','Name the next action, owner, fixed date and decision rule. Preserve the original plan.')]]
 for pg,g in enumerate(groups,1):
  base(c,'Business plan template','Blank narrative worksheet - use evidence, not the example figures from another business.',pg,3)
  for i,(num,title,prompt) in enumerate(g):section(c,610-i*175,f'{num}. {title}',prompt,4)
  if pg==3:
   section(c,260,'Assumption register','Input / unit / evidence source / date / owner. Add a separate cash schedule when needed.',4)
  c.setFont('D2',8);c.drawString(42,62,'This short worksheet does not certify readiness or replace recipient-specific financing documents.');c.showPage()
 c.save()
def check_pdf():
 c=canvas.Canvas(str(O/'business-startup-checklist.pdf'),pagesize=letter);c.setTitle('Business Startup Checklist - Blank and Fictional Example');c.setAuthor('NexalyPlanner')
 rows=[('Define buyer / interview brief','Owner','Nov 3','Done / required','Dated brief saved; fictional example.'),('Write service scope','Owner','Nov 4','Done / required','Draft inclusions and exclusions reviewed; fictional.'),('Check local requirements','Owner','Nov 4','Blocked / required','Awaiting official-source check; not certified.'),('Prepare dated cash plan','Owner','Nov 7','In progress / required','Receipt and payment dates still need checking.'),('Test delivery and backup','Owner','Nov 8','Not started / required','Evidence not recorded.'),('Physical shop fit-out','Owner','-','N/A / optional','No physical retail premises in this fictional service.')]
 for pg in [1,2]:
  base(c,'Business startup checklist','Blank six-action sheet' if pg==1 else 'Fictional studio review as of 2026-11-05 - statuses are manual records.',pg,2)
  c.setFont('D2B',8);c.setFillColor(TEAL);c.rect(42,608,528,22,fill=1,stroke=0);c.setFillColor(HexColor('#ffffff'))
  for x,label in [(48,'Action'),(292,'Owner'),(365,'Due'),(435,'Status / importance')]:c.drawString(x,616,label)
  for i in range(6):
   y=530-i*75;c.setStrokeColor(LINE);c.rect(42,y,528,75,stroke=1,fill=0);c.setFillColor(INK);c.setFont('D2',8)
   if pg==2:
    for x,value in zip([48,292,365,435],rows[i][:4]):
     for j,line in enumerate(textwrap.wrap(value,44 if x==48 else 23 if x==435 else 13)):c.drawString(x,y+56-j*12,line)
    c.drawString(48,y+16,'Evidence / reason: '+rows[i][4])
   else:c.drawString(48,y+16,'Evidence / not-applicable reason: ____________________________________________')
  c.setFont('D2',9)
  if pg==2:c.drawString(42,132,'2 of 5 applicable required actions done (40%); 3 open; 1 blocked; 1 overdue.')
  else:c.drawString(42,132,'Required done: ____ / applicable required: ____   Open: ____   Blocked: ____')
  c.drawString(42,107,'Done needs evidence. Not applicable needs a reason. Keep the fixed review date.')
  c.setFont('D2',8);c.drawString(42,62,'A task summary is not legal compliance, launch approval or verification of supporting documents.');c.showPage()
 c.save()
plan_pdf();check_pdf()
t=(R/'tools/business-plan-cover-page/index.html').read_text();nav=t[t.index('<header class="nav">'):t.index('</header>')+9];footer=t[t.index('<footer class="site">'):t.index('</footer>')+9]
labels={'customer':'Customer and evidence','offer':'Offer and revenue model','market':'Market and alternatives','operations':'Operations and capacity','marketing':'Marketing and sales','finance':'Costs, cash and funding assumptions','risks':'Risks and downside case','review':'Actions, owners and review dates'}
prompts={'customer':'Who has the problem? Which dated observations support it?','offer':'Selling unit, price assumption, inclusions and exclusions.','market':'Compare real alternatives and list untested claims.','operations':'Owner, hours, stock, equipment, acceptance and dependencies.','marketing':'Channel, sales steps, test ceiling and measurement.','finance':'Separate revenue, consumed costs, purchases, receipts and dated payments.','risks':'Change one major assumption and record the consequence.','review':'Specific action, owner, fixed review date and decision rule.'}
configs=[{'slug':'business-plan-template','title':'Free Business Plan Template: Editable HTML & PDF','desc':'Write an eight-section business plan in a free editable worksheet. Download printable HTML, a JSON backup and an original three-page PDF template.','intro':'Capture your own business assumptions in eight narrative sections. This is a manual template, not AI-generated advice or a financial-statement calculator.','guide':'''<h2>Choose the right business plan format</h2><p>Use this short operating template to connect a customer, offer, evidence, delivery, costs, cash and review decisions. The <a href="https://www.sba.gov/business-guide/plan-your-business/write-your-business-plan">SBA business-plan guidance</a> distinguishes lean and more detailed planning approaches. A lender or investor may require additional statements, projections and supporting documents; this worksheet does not guarantee acceptance.</p><h3>How to use the editable template</h3><ol><li>Enter a business name and a fixed plan date.</li><li>Complete customer, offer, alternatives, operations, marketing, finance, risks and review sections. Each accepts up to 1,800 characters.</li><li>Review the draft. Blank sections remain visibly marked; filled sections are not automatically verified.</li><li>Keep evidence for quantities, hours, costs and dates separately. Do not paste sensitive customer records into a public plan.</li><li>Download a JSON backup before leaving. Download HTML for a standalone static document, or use browser print / Save PDF.</li></ol><h3>What the downloads contain</h3><p>The original PDF is three blank US Letter portrait writing pages with eight sections and an assumption register. It is static, not a fillable form. HTML contains your entered narrative in a standalone printable page; edit here and export again when the plan changes. JSON reopens editable entries in this exact worksheet. No Word, Excel or automatically calculated projection file is included.</p><h3>Fictional filled example</h3><p>The sample studio models two $240 projects, $80 total direct cost and $400 before owner time and overhead. At a 50% deposit, initial receipts are $240. Two six-hour projects use all 12 available delivery hours before buffer. A downside of eight hours per project needs 16 hours, four more than available. These are assumptions, not market rates or a viable-business certification.</p><h3>Evidence and version control</h3><p>A fixed date identifies the document version; it does not update itself tomorrow. Retain the original forecast and explain revisions. The worksheet stores no entries automatically. A backup is editable; an exported HTML or printed report is not a replacement for your evidence.</p><p>Choose a relevant <a href="/journal/business-plan-examples/">worked business-plan example</a>, track preparation in the <a href="/tools/business-startup-checklist/">startup checklist</a>, and use the separate <a href="/tools/business-plan-cover-page/">cover-page builder</a> when a front sheet is needed.</p>'''}, {'slug':'business-startup-checklist','title':'Free Business Startup Checklist: Evidence, Owners & PDF','desc':'Track startup actions with owners, due dates, evidence and blockers. Review required tasks, keep a JSON backup and download a CSV or printable PDF.','intro':'Turn preparation into assigned actions with evidence. Statuses are your manual records; this checklist does not verify permits, legal compliance or launch readiness.','guide':'''<h2>Use a startup checklist with evidence</h2><p>Start with the customer problem, offer, market evidence, service scope, dated cash needs, delivery capacity and the requirements relevant to your actual business and location. This is an organizational checklist, not a universal list of legal obligations. Use the <a href="https://www.sba.gov/business-guide/launch-your-business">SBA launch guide</a> and responsible local official sources for the requirements that apply.</p><h3>Fields and limits</h3><p>Enter a project name (up to 100 characters) and a fixed review date. Add 1–30 actions, each with a task (200 characters), owner (80), optional real due date, importance, status and evidence/reason (500). Marking Done requires evidence text; Not applicable requires a reason. The worksheet does not inspect or authenticate the evidence.</p><h3>How the report is calculated</h3><p>Applicable required actions exclude rows you mark Not applicable. Required done divided by applicable required gives the displayed percentage. Open required actions are applicable required rows not marked Done. Overdue means an open required row has a due date before the fixed review date; a task due on that date is not counted overdue. If no applicable required actions exist, no completion percentage is shown and readiness is not established.</p><h3>Fictional sample</h3><p>The studio has six actions: five required and one optional marked Not applicable with a reason. Two required actions are Done, three remain open, one is Blocked and one is overdue as of November 5, 2026. Completion is 2 ÷ 5 = 40%. This is a task summary, not approval to trade.</p><h3>Keep a copy and review blockers</h3><p>Entries remain only on this page until you choose a JSON backup. Import previews a valid same-tool backup before replacing the page. CSV exports the reviewed rows, with spreadsheet-formula protection. Browser Print / Save PDF prints the report. The downloadable two-page static Letter PDF has a six-row blank sheet and a filled fictional example; it is not a fillable or automated checklist.</p><p>Use the <a href="/tools/business-plan-template/">business-plan template</a> for the narrative and <a href="/journal/entrepreneurial-skills-practice-plan/">skills practice plan</a> for small evidence-building exercises. Paid planners are separate products and these backups do not imply paid-product import compatibility.</p>'''}]
for a in configs:
 slug=a['slug'];isplan=slug=='business-plan-template';url='https://nexalyplanner.com/tools/'+slug+'/'
 fields='<div class="d1-grid"><label>Business / project name (required)<input id="d2-name" maxlength="100" required></label><label>Fixed review date (required)<input id="d2-asof" type="date" required></label></div>'
 fields+=''.join(f'<div class="d2-section"><label>{label}<textarea id="d2-{k}" maxlength="1800" placeholder="{prompts[k]}"></textarea></label></div>' for k,label in labels.items()) if isplan else '<div id="d2-rows"></div><button id="d2-add" type="button">Add action</button>'
 schema={'@context':'https://schema.org','@type':'WebApplication','name':a['title'],'url':url,'applicationCategory':'BusinessApplication','operatingSystem':'Web browser','isAccessibleForFree':True,'offers':{'@type':'Offer','price':'0','priceCurrency':'USD'}}
 head=f'<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(a["title"])}</title><meta name="description" content="{E(a["desc"])}"><link rel="canonical" href="{url}"><link rel="stylesheet" href="/assets/css/style.css?v=7e6083e6f963"><link rel="stylesheet" href="/assets/css/day1-planning-tools.css?v=20261104"><link rel="stylesheet" href="/assets/css/day2-planning-tools.css?v=20261105"><script type="application/ld+json">{json.dumps(schema)}</script></head><body>'
 page=head+nav+f'<main class="d1" data-day2="{slug}"><nav aria-label="Breadcrumb"><a href="/tools/">Free planners</a> / {E(a["title"])}</nav><div class="d1-hide"><p>FREE · NO ACCOUNT NEEDED</p><h1>{E(a["title"])}</h1><p>{a["intro"]}</p><a class="d1-download" href="/downloads/{slug}.pdf" download>Download '+('three-page plan PDF' if isplan else 'blank + example checklist PDF')+'</a><p>Published November 5, 2026 · By NexalyPlanner</p><noscript><p>Editable controls require JavaScript. The PDF and guide remain available.</p></noscript></div><section class="d1-panel d1-hide"><h2>Prepare your worksheet</h2><form id="d2-form">'+fields+'<button type="submit">Review current inputs</button><button id="d2-sample" type="button">Load fictional example</button></form><p id="d2-status" role="status" aria-live="polite"></p></section><section class="d1-panel d1-report"><h2>Your reviewed report</h2><div id="d2-result" aria-live="polite"><p>Enter your details and review to create a report.</p></div></section><section class="d1-panel d1-hide"><h2>Keep your work</h2><p>No automatic saving or cross-device sync. Closing or reloading loses page entries unless you keep a backup. This worksheet does not send entries to a server. Downloads are separate from paid planner data formats.</p><button id="d2-backup" type="button">Download JSON backup</button><label>Import same-tool JSON backup (128 KB maximum)<input id="d2-import" type="file" accept=".json,application/json"></label><button id="d2-export" type="button">'+('Download printable HTML' if isplan else 'Download checklist CSV')+'</button><button id="d2-print" type="button">Print / Save PDF</button><button id="d2-clear" type="button">Clear page entries</button><p>Review after every edit before exporting. Print opens the browser dialog; PDF saving depends on your device. Check print preview, paper size and pagination.</p><dialog id="d2-import-dialog"><h2>Replace current entries?</h2><p>A valid backup has been checked for this worksheet. Importing replaces what is currently on this page.</p><button id="d2-confirm" type="button">Replace entries</button><button id="d2-cancel" type="button">Cancel</button></dialog><dialog id="d2-clear-dialog"><h2>Clear page entries?</h2><p>Downloaded backups remain on your device.</p><button id="d2-clear-confirm" type="button">Clear entries</button><button id="d2-clear-cancel" type="button">Cancel</button></dialog></section><section class="d1-panel d1-hide">'+a['guide']+'</section></main>'+footer+'<div id="toast" class="toast" role="status"></div><script src="/assets/js/main.js?v=aad28232fa7f" defer></script><script src="/assets/js/day2-planning-tools.js?v=20261105" defer></script></body></html>'
 path=R/'tools'/slug/'index.html';path.parent.mkdir(exist_ok=True);path.write_text(page)
